// ============================================
// FETCH ALL MARKET DATA - MarketPulse v6.0 (CN)
// China Market Edition
// IPv4 Fix: Uses custom DNS resolver
// Data Sources: Yahoo Finance, World Bank
// ============================================

const dns = require('dns');
dns.setDefaultResultOrder('ipv4first');

const results = {
  // China Market Indices
  csi300: 'N/A',
  csi300Change: 'N/A',
  sseComposite: 'N/A',
  sseCompositeChange: 'N/A',
  szseComponent: 'N/A',
  szseComponentChange: 'N/A',
  hangSeng: 'N/A',
  hangSengChange: 'N/A',
  // Commodities & Forex
  gold: 'N/A',
  goldChange: 'N/A',
  usdCny: 'N/A',
  usdCnyChange: 'N/A',
  // Economic Indicators (World Bank - China)
  gdpValue: 'N/A',
  gdpYear: 'N/A',
  cpiValue: 'N/A',
  cpiYear: 'N/A',
  unemploymentValue: 'N/A',
  unemploymentYear: 'N/A',
  // News Headlines
  headlines: 'No headlines available'
};

// --- Helper Functions ---

async function fetchWithRetry(url, options = {}, retries = 3) {
  for (let i = 0; i < retries; i++) {
    try {
      const response = await $http.request({
        method: 'GET',
        url: url,
        headers: options.headers || { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
        timeout: options.timeout || 30000,
        ...(options.json === false ? { encoding: 'utf-8', json: false } : {})
      });
      return response;
    } catch (e) {
      if (i === retries - 1) throw e;
      await new Promise(r => setTimeout(r, 1000 * (i + 1)));
    }
  }
}

function formatPct(price, prevClose) {
  if (!price || !prevClose || prevClose === 0) return 'N/A';
  const changePct = ((price - prevClose) / prevClose) * 100;
  const sign = changePct >= 0 ? '+' : '';
  return sign + changePct.toFixed(2) + '%';
}

// --- 1. FETCH CHINA MARKET INDICES (Yahoo Finance) ---

const indices = [
  { symbol: '000300.SS', namePrice: 'csi300', nameChange: 'csi300Change', label: 'CSI 300' },
  { symbol: '000001.SS', namePrice: 'sseComposite', nameChange: 'sseCompositeChange', label: 'SSE Composite' },
  { symbol: '399001.SZ', namePrice: 'szseComponent', nameChange: 'szseComponentChange', label: 'SZSE Component' },
  { symbol: '^HSI', namePrice: 'hangSeng', nameChange: 'hangSengChange', label: 'Hang Seng' }
];

for (const idx of indices) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(idx.symbol) + '?interval=1d&range=1d',
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
      timeout: 15000
    });

    if (data && data.chart && data.chart.result && data.chart.result[0]) {
      const meta = data.chart.result[0].meta;
      const price = meta.regularMarketPrice;
      const prevClose = meta.chartPreviousClose || meta.previousClose;

      if (price) {
        results[idx.namePrice] = price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        if (prevClose && prevClose > 0) {
          results[idx.nameChange] = formatPct(price, prevClose);
        }
      }
    }
    // Rate limit: small delay between requests
    await new Promise(r => setTimeout(r, 500));
  } catch (e) {
    console.log(idx.label + ' error: ' + e.message);
  }
}

// --- 2. FETCH GOLD & USD/CNY (Yahoo Finance) ---

const fxCommodities = [
  { symbol: 'GC=F', namePrice: 'gold', nameChange: 'goldChange', label: 'Gold', prefix: '$' },
  { symbol: 'CNY=X', namePrice: 'usdCny', nameChange: 'usdCnyChange', label: 'USD/CNY', prefix: '' }
];

for (const item of fxCommodities) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(item.symbol) + '?interval=1d&range=1d',
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
      timeout: 15000
    });

    if (data && data.chart && data.chart.result && data.chart.result[0]) {
      const meta = data.chart.result[0].meta;
      const price = meta.regularMarketPrice;
      const prevClose = meta.chartPreviousClose || meta.previousClose;

      if (price) {
        if (item.symbol === 'CNY=X') {
          results[item.namePrice] = item.prefix + price.toFixed(4);
        } else {
          results[item.namePrice] = item.prefix + price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        }
        if (prevClose && prevClose > 0) {
          results[item.nameChange] = formatPct(price, prevClose);
        }
      }
    }
    await new Promise(r => setTimeout(r, 500));
  } catch (e) {
    console.log(item.label + ' error: ' + e.message);
  }
}

// --- 3. FETCH CHINA ECONOMIC DATA (World Bank API) ---

// GDP Growth
try {
  const gdpData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.worldbank.org/v2/country/CN/indicator/NY.GDP.MKTP.KD.ZG?format=json&per_page=5&mrv=1',
    timeout: 30000
  });

  if (gdpData && gdpData[1] && gdpData[1][0]) {
    const obs = gdpData[1][0];
    if (obs.value !== null) {
      const sign = obs.value >= 0 ? '+' : '';
      results.gdpValue = sign + parseFloat(obs.value).toFixed(2) + '%';
      results.gdpYear = obs.date;
    }
  }
} catch (e) {
  console.log('World Bank GDP error: ' + e.message);
}

// CPI Inflation
try {
  const cpiData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.worldbank.org/v2/country/CN/indicator/FP.CPI.TOTL.ZG?format=json&per_page=5&mrv=1',
    timeout: 30000
  });

  if (cpiData && cpiData[1] && cpiData[1][0]) {
    const obs = cpiData[1][0];
    if (obs.value !== null) {
      results.cpiValue = parseFloat(obs.value).toFixed(2) + '%';
      results.cpiYear = obs.date;
    }
  }
} catch (e) {
  console.log('World Bank CPI error: ' + e.message);
}

// Unemployment Rate
try {
  const unempData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.worldbank.org/v2/country/CN/indicator/SL.UEM.TOTL.ZS?format=json&per_page=5&mrv=1',
    timeout: 30000
  });

  if (unempData && unempData[1] && unempData[1][0]) {
    const obs = unempData[1][0];
    if (obs.value !== null) {
      results.unemploymentValue = parseFloat(obs.value).toFixed(2) + '%';
      results.unemploymentYear = obs.date;
    }
  }
} catch (e) {
  console.log('World Bank Unemployment error: ' + e.message);
}

// --- 4. FETCH NEWS HEADLINES (Reuters China, Sina Finance RSS) ---

try {
  // Try Reuters China news first
  const rssResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://news.google.com/rss/search?q=China+stock+market+economy&hl=en&gl=US&ceid=US:en',
    timeout: 30000,
    json: false
  });

  if (rssResponse && typeof rssResponse === 'string') {
    const titleMatches = rssResponse.match(/<title>([^<]+)<\/title>/g);

    if (titleMatches && titleMatches.length > 1) {
      const titles = [];
      for (let i = 1; i < Math.min(titleMatches.length, 9); i++) {
        let title = titleMatches[i].replace(/<\/?title>/g, '');
        title = title.trim();
        title = title.replace(/&#x201c;/g, '"');
        title = title.replace(/&#x201d;/g, '"');
        title = title.replace(/&#x2019;/g, "'");
        title = title.replace(/&#x2018;/g, "'");
        title = title.replace(/&#x2014;/g, ' - ');
        title = title.replace(/&#x2013;/g, '-');
        title = title.replace(/&amp;/g, '&');
        title = title.replace(/&quot;/g, '"');
        title = title.replace(/&#xa0;/g, ' ');
        title = title.replace(/ - .*$/, ''); // Remove source attribution

        if (title.length > 10) {
          titles.push(i + '. ' + title);
        }
      }

      if (titles.length > 0) {
        results.headlines = titles.join('\n');
      }
    }
  }
} catch (e) {
  console.log('RSS error: ' + e.message);
}

return [{ json: results }];

// ============================================
// FETCH CHINA STOCK PRICES - MarketPulse v6.0 (CN)
// Stocks: Moutai, CATL, BYD, Alibaba HK, Tencent HK
// IPv4 Fix included
// ============================================

const dns = require('dns');
dns.setDefaultResultOrder('ipv4first');

const watchlistStr = $input.first().json.watchlist || '';
const symbols = watchlistStr.split(',').map(s => s.trim()).filter(s => s.length > 0);

const stockNames = {
  '600519.SS': 'Moutai',
  '300750.SZ': 'CATL',
  '002594.SZ': 'BYD',
  '9988.HK': 'Alibaba',
  '0700.HK': 'Tencent',
  '1810.HK': 'Xiaomi',
  'PDD': 'PDD',
  'NIO': 'NIO',
  'BABA': 'Alibaba US',
  'JD': 'JD.com'
};

const currencySymbols = {
  'CNY': '¥',
  'HKD': 'HK$',
  'USD': '$'
};

const stockResults = [];

for (const symbol of symbols) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(symbol) + '?interval=1d&range=1d',
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
      timeout: 15000
    });

    if (data && data.chart && data.chart.result && data.chart.result[0]) {
      const meta = data.chart.result[0].meta;
      const price = meta.regularMarketPrice;
      const prevClose = meta.chartPreviousClose || meta.previousClose;
      const currency = meta.currency || 'CNY';
      const currSymbol = currencySymbols[currency] || currency + ' ';
      const name = stockNames[symbol] || meta.shortName || symbol;

      if (price) {
        let changePct = 'N/A';
        let changeArrow = '';
        if (prevClose && prevClose > 0) {
          const pct = ((price - prevClose) / prevClose) * 100;
          const sign = pct >= 0 ? '+' : '';
          changePct = sign + pct.toFixed(2) + '%';
          changeArrow = pct >= 0 ? '▲' : '▼';
        }

        stockResults.push({
          symbol: symbol,
          name: name,
          price: currSymbol + price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
          change: changePct,
          arrow: changeArrow,
          currency: currency
        });
      }
    }
    // Rate limit
    await new Promise(r => setTimeout(r, 500));
  } catch (e) {
    console.log('Stock ' + symbol + ' error: ' + e.message);
    stockResults.push({
      symbol: symbol,
      name: stockNames[symbol] || symbol,
      price: 'N/A',
      change: 'N/A',
      arrow: '',
      currency: 'N/A'
    });
  }
}

// Format watchlist summary
let watchlistSummary = 'Watchlist data unavailable';
if (stockResults.length > 0) {
  const lines = stockResults.map(s => {
    return s.arrow + ' ' + s.name + ' (' + s.symbol + '): ' + s.price + ' (' + s.change + ')';
  });
  watchlistSummary = lines.join('\n');
}

return [{ json: { watchlistSummary: watchlistSummary, stockDetails: stockResults } }];

// ============================================
// COMBINE ALL DATA - MarketPulse v6.0 (CN)
// Merges China market data + stock prices
// ============================================

const items = $input.all();
const combined = {};

for (const item of items) {
  const j = item.json || {};
  for (const key of Object.keys(j)) {
    if (j[key] !== undefined && j[key] !== null) {
      combined[key] = j[key];
    }
  }
}

return [{ json: combined }];

// ============================================
// COMPOSE TELEGRAM MESSAGE - MarketPulse v6.0 (CN)
// China Market Edition with color indicators
// ============================================

const items = $input.all();
const now = new Date();

let d = {
  csi300: 'N/A',
  csi300Change: 'N/A',
  sseComposite: 'N/A',
  sseCompositeChange: 'N/A',
  szseComponent: 'N/A',
  szseComponentChange: 'N/A',
  hangSeng: 'N/A',
  hangSengChange: 'N/A',
  gold: 'N/A',
  goldChange: 'N/A',
  usdCny: 'N/A',
  usdCnyChange: 'N/A',
  gdpValue: 'N/A',
  gdpYear: 'N/A',
  cpiValue: 'N/A',
  cpiYear: 'N/A',
  unemploymentValue: 'N/A',
  unemploymentYear: 'N/A',
  watchlistSummary: 'N/A',
  llmAnalysis: 'Analysis unavailable'
};

for (const item of items) {
  const j = item.json || {};
  for (const key of Object.keys(d)) {
    if (j[key] && j[key] !== 'N/A' && j[key] !== 'Unknown' && j[key] !== 'Analysis unavailable') {
      d[key] = j[key];
    }
  }
  if (j.text && j.text.length > 30) d.llmAnalysis = j.text;
  if (j.response && j.response.length > 30) d.llmAnalysis = j.response;
}

const dateStr = now.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

// Color indicators for index changes
function changeIndicator(changeStr) {
  if (!changeStr || changeStr === 'N/A') return '⚪';
  const val = parseFloat(changeStr);
  if (isNaN(val)) return '⚪';
  if (val >= 2) return '🟢🟢';
  if (val > 0) return '🟢';
  if (val === 0) return '🟡';
  if (val > -2) return '🔴';
  return '🔴🔴';
}

// Market direction arrows
function arrow(changeStr) {
  if (!changeStr || changeStr === 'N/A') return '';
  return changeStr.startsWith('+') ? '▲' : '▼';
}

// USD/CNY strength indicator
function cnyIndicator(changeStr) {
  if (!changeStr || changeStr === 'N/A') return '';
  const val = parseFloat(changeStr);
  if (isNaN(val)) return '';
  // For USD/CNY: positive = CNY weakening, negative = CNY strengthening
  if (val > 0) return '(CNY Weakening)';
  if (val < 0) return '(CNY Strengthening)';
  return '(Stable)';
}

const message = `📊 MarketPulse Daily Digest (CN)
━━━━━━━━━━━━━━━━━━━━
📅 ${dateStr}
🇨🇳 China Market Edition

📈 CHINA MARKET INDICES
${changeIndicator(d.csi300Change)} ${arrow(d.csi300Change)} CSI 300: ${d.csi300} (${d.csi300Change})
${changeIndicator(d.sseCompositeChange)} ${arrow(d.sseCompositeChange)} SSE Composite: ${d.sseComposite} (${d.sseCompositeChange})
${changeIndicator(d.szseComponentChange)} ${arrow(d.szseComponentChange)} SZSE Component: ${d.szseComponent} (${d.szseComponentChange})
${changeIndicator(d.hangSengChange)} ${arrow(d.hangSengChange)} Hang Seng: ${d.hangSeng} (${d.hangSengChange})

💰 COMMODITIES & FOREX
${arrow(d.goldChange)} Gold: ${d.gold} (${d.goldChange})
${arrow(d.usdCnyChange)} USD/CNY: ${d.usdCny} (${d.usdCnyChange}) ${cnyIndicator(d.usdCnyChange)}

📊 ECONOMIC INDICATORS (CHINA)
• GDP Growth (${d.gdpYear}): ${d.gdpValue}
• Inflation/CPI (${d.cpiYear}): ${d.cpiValue}
• Unemployment (${d.unemploymentYear}): ${d.unemploymentValue}

📋 WATCHLIST
${d.watchlistSummary}

💡 AI ANALYSIS
${d.llmAnalysis}

━━━━━━━━━━━━━━━━━━━━
⚠️ Disclaimer: AI-generated analysis for informational purposes only. Not financial advice.

📎 Sources: Yahoo Finance, World Bank, Google News

MarketPulse v6.0 (CN) | Manus AI & Claude Code`;

return [{ json: { message: message, timestamp: now.toISOString() } }];

const alertMessage = `⚠️ MarketPulse (CN) Error

Time: ${new Date().toISOString()}

Check n8n dashboard for details.`;
return [{ json: { alertMessage } }];
